{
  "title": "Discussion about living and working abroad in Central Europe",
  "topics": [
    {
      "id": "living-abroad",
      "title": "Who lives abroad and experiences in Slovakia and Austria",
      "claims": [
        {
          "text": "Some participants have lived in Slovakia for about a year (P1)",
          "evidence": [43, 44, 45]
        },
        {
          "text": "P3 mentions being in Austria since 17.11.2025 and in Slovakia since 03.09.2025",
          "evidence": [49, 54]
        },
        {
          "text": "P2 lists acquaintances abroad: @AndriiRaccoon in Austria and walternet134 in Poland",
          "evidence": [3]
        }
      ]
    },
    {
      "id": "job-search-abroad",
      "title": "Finding jobs abroad and the application process",
      "claims": [
        {
          "text": "P3 applied to around 100 vacancies and got only 3 interviews",
          "evidence": [21, 22]
        },
        {
          "text": "P3 suggests using LinkedIn for job hunting",
          "evidence": [18]
        },
        {
          "text": "P3 received a higher salary but accepted a minimal salary because of urgency",
          "evidence": [37, 39]
        },
        {
          "text": "P3 applied to positions regardless of language requirements and often succeeded",
          "evidence": [36, 29]
        }
      ]
    },
    {
      "id": "language-requirements",
      "title": "Importance of local language knowledge",
      "claims": [
        {
          "text": "95% of vacancies state a requirement for local language proficiency",
          "evidence": [26]
        },
        {
          "text": "Employers commonly ask for B2 level, sometimes B1, and rarely require a certificate",
          "evidence": [46]
        },
        {
          "text": "P1 feels insecure about using English outside of work",
          "evidence": [51, 52]
        },
        {
          "text": "P3 is learning the local language to feel more comfortable in daily life",
          "evidence": [47]
        }
      ]
    },
    {
      "id": "salary-comparison",
      "title": "Salary expectations in Europe vs Ukraine",
      "claims": [
        {
          "text": "Salaries in Europe are generally higher than in Ukraine, but many candidates ignore this factor",
          "evidence": [35]
        }
      ]
    },
    {
      "id": "networking-events",
      "title": "Attending tech events and language practice",
      "claims": [
        {
          "text": "P3 considers attending a tech event in Warsaw (wawtech.io/summer)",
          "evidence": [59]
        },
        {
          "text": "P1 suggests joining Discord channels to improve spoken English",
          "evidence": [56, 57]
        }
      ]
    }
  ],
  "decisions": [],
  "openQuestions": [
    {
      "text": "Will P3 stay in Austria long‑term or consider moving to another European country?",
      "evidence": [60]
    }
  ]
}
